CREATE COLUMN TABLE "TEST_AP"."NNM3" ("ObjectCode" NVARCHAR(20) NOT NULL , "Series" INTEGER CS_INT DEFAULT 0 NOT NULL , "DocSubType" NVARCHAR(2) DEFAULT '--' NOT NULL , "logInstanc" INTEGER CS_INT, PRIMARY KEY ("ObjectCode", "DocSubType", "Series")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE INDEX "NNM3_SERIES" ON "TEST_AP"."NNM3" ( "Series" ASC )